function buildWhy(proj,c){ let good=[]; if(marketBase(c.market)==='totals'){good=proj.modules.filter(m=>/offense|starting pitcher|staff pitching|bullpen|environment/i.test(m.name)).sort((a,b)=>b.confidence-a.confidence).slice(0,4);}else{const wantHome=sameTeam(c.selection,proj.home_team);good=proj.modules.filter(m=>wantHome?m.value>0:m.value<0).sort((a,b)=>Math.abs(b.value)*b.confidence-Math.abs(a.value)*a.confidence).slice(0,3);} return `${c.thesis}. Independent projection ${proj.away_team} ${proj.projected_score.away??'—'} – ${proj.home_team} ${proj.projected_score.home??'—'}. Primary supporting modules: ${good.map(m=>`${m.name} (${m.evidence})`).join(' | ')||'limited structured evidence'}.`; }
function timing(event,c,proj){ const hrs=hoursUntil(event.commence_time),fresh=c.last_update?Math.abs(Date.now()-new Date(c.last_update).getTime())/60000:null; if(proj.data_quality<65||(proj.coverage_score??0)<58)return 'WAIT / PASS FOR CONFIRMATION'; if(event.sport_key==='baseball_mlb'&&hrs<=4&&!proj.lineups_confirmed)return 'WAIT — starting lineups are not fully confirmed'; if(c.sanity_flags?.length&&c.independent_disagreement>=.08)return 'WAIT — market disagreement requires stronger confirmation'; if(hrs>12)return 'WAIT — re-sync closer to game'; if(fresh!=null&&fresh>45)return 'WAIT — quote may be stale'; return 'BET NOW if target-book line still matches'; }
function finalVerification(proj,c){ const flags=[]; if((c.estimated_ev??0)<=0)flags.push('calibrated estimated EV is non-positive'); if((c.adjusted_edge??0)<(c.cushion??0))flags.push('adjusted edge is below the market-specific required cushion'); if(proj.data_quality<80)flags.push('data quality below Core threshold'); if((c.market_coverage??proj.coverage_score??0)<76)flags.push('market-specific model coverage below Core threshold'); if((c.market_edge_count??proj.independent_edge_count)<2)flags.push('fewer than two market-specific independent edges'); if((c.market_support_strength??0)<42)flags.push('market-specific support strength is below the Secondary threshold'); if((c.market_effective_agreement??proj.effective_agreement??proj.model_agreement)<69)flags.push('market-specific effective agreement below Core threshold'); if(c.market_inside_fair_range)flags.push('market price remains inside the calibrated uncertainty band'); if(!c.hard_rock)flags.push('Hard Rock price not verified'); if(c.sanity_flags?.length)flags.push(c.sanity_flags[0]); if(proj.risks.length)flags.push(proj.risks[0]); return flags.length?`Caution: ${[...new Set(flags)].join('; ')}.`:'Core release gates checked: data quality, coverage, effective agreement, two-edge gate, uncertainty-band separation, market sanity, price cushion, target book, and failure paths.'; }


function settledBetOutcome(record,score){
  if(!score||!score.final)return null;
  const hs=Number(score.home_score),as=Number(score.away_score); if(!Number.isFinite(hs)||!Number.isFinite(as))return null;
  const market=record.market,sel=String(record.selection||''),point=Number(record.point),inn=mlbPeriodInnings(market),base=marketBase(market);
  const usePeriod=inn!=null&&score.period_scores&&score.period_scores[inn],pScore=usePeriod?score.period_scores[inn]:null; const H=usePeriod?Number(pScore.home):hs,A=usePeriod?Number(pScore.away):as;
  let z=0;
  if(base==='h2h'){
    const homeSel=sameTeam(sel,record.home_team),awaySel=sameTeam(sel,record.away_team);
    if(!homeSel&&!awaySel)return null;
    z=homeSel?H-A:A-H;
  } else if(base==='spreads'){
    const homeSel=sameTeam(sel,record.home_team),awaySel=sameTeam(sel,record.away_team);
    if((!homeSel&&!awaySel)||!Number.isFinite(point))return null;
    z=(homeSel?H-A:A-H)+point;
  } else if(base==='totals'){
    if(!Number.isFinite(point))return null;
    z=H+A-point;
    if(sel.toLowerCase()==='under')z=-z;
  } else return null;
  return z>1e-9?'WIN':z<-1e-9?'LOSS':'PUSH';
}
async function resolveFinalScore(record){
  try{
    if(record.sport_key==='baseball_mlb'){
      const data=await mlbSchedule(record.commence_time);
      const g=mlbGameMatch(data,{home_team:record.home_team,away_team:record.away_team});
      if(!g)return {final:false,status:'NOT_FOUND'};
      const final=g.status?.abstractGameState==='Final'||g.status?.detailedState==='Final'; let period_scores={};
      if(final&&g.gamePk){try{const feed=await cachedJson(`https://statsapi.mlb.com/api/v1.1/game/${g.gamePk}/feed/live`,24*3600*1000),innings=feed.liveData?.linescore?.innings||[];let hh=0,aa=0;for(let i=0;i<Math.min(7,innings.length);i++){hh+=num(innings[i]?.home?.runs,0);aa+=num(innings[i]?.away?.runs,0);if([1,3,5,7].includes(i+1))period_scores[i+1]={home:hh,away:aa};}}catch{}}
      return {final, status:g.status?.detailedState||g.status?.abstractGameState||'', home_score:num(g.teams?.home?.score), away_score:num(g.teams?.away?.score), period_scores, source:'MLB Stats API'};
    }
    const cfg=ESPN[record.sport_key]; if(!cfg)return {final:false,status:'NO_FREE_RESULT_PROVIDER'};
    const board=await espnBoard(cfg,record.commence_time);
    const e=espnEventMatch(board,{home_team:record.home_team,away_team:record.away_team});
    if(!e)return {final:false,status:'NOT_FOUND'};
    const c=e.competitions?.[0],st=c?.status?.type||e.status?.type||{};
    const h=(c?.competitors||[]).find(x=>x.homeAway==='home'),a=(c?.competitors||[]).find(x=>x.homeAway==='away');
    const final=!!(st.completed||st.name==='STATUS_FINAL');
    return {final,status:st.description||st.detail||st.name||'',home_score:num(h?.score),away_score:num(a?.score),source:'ESPN structured scoreboard'};
  }catch(err){ return {final:false,status:'ERROR',error:err.message}; }
}

async function scanSlate(events){
  const capped=pregameOnly(events).slice(0,MAX_SCAN_GAMES), prelim=[];
  for(const e of capped){ try{const proj=await analyzeEvent(e); prelim.push({event:sanitizeEvent(e),projection:proj});}catch(err){prelim.push({event:sanitizeEvent(e),projection:lowInfoProjection(e,err.message,30)});} }
  let deepMeta={enabled:false,games:0,markets:[],quota_remaining:LAST_ODDS_META?.remaining??null,note:'Featured markets only.'};
  if(capped.some(e=>e.sport_key==='baseball_mlb')&&ODDS_KEY){
    const maxN=deepGameCount(), candidates=prelim.filter(a=>a.event.sport_key==='baseball_mlb'&&a.projection?.f5).map(a=>({...a,research_priority:mlbDeepPriority(a.projection)})).sort((a,b)=>b.research_priority-a.research_priority);
    const ranked=candidates.filter((a,i)=>i<1||a.research_priority>=2.15).slice(0,maxN); let credits=0,got=0; const marketsUsed=new Set();
    for(let i=0;i<ranked.length;i++){const a=ranked[i],sets=[['h2h_1st_5_innings','spreads_1st_5_innings','totals_1st_5_innings']]; if(i===0&&Number(LAST_ODDS_META?.remaining||999)>180)sets.push(['h2h_1st_3_innings','spreads_1st_3_innings','totals_1st_3_innings','totals_1st_1_innings']); for(const ks of sets){if(credits+ks.length>MAX_DEEP_MARKET_CREDITS)continue;try{const ex=await deepEventOdds(a.event,ks.join(','));credits+=ks.length;ks.forEach(k=>marketsUsed.add(k));if(ex?.bookmakers?.length){a.event=mergeEventMarkets(a.event,ex);got++;}}catch(err){a.deep_market_error=err.message;}}}
    // copy enriched events back to prelim by id
    for(const r of ranked){const idx=prelim.findIndex(x=>x.event.id===r.event.id);if(idx>=0)prelim[idx].event=r.event;}
    deepMeta={enabled:true,games:new Set(ranked.filter(r=>(r.event.bookmakers||[]).some(b=>(b.markets||[]).some(m=>isMlbPeriodMarket(m.key)))).map(r=>r.event.id)).size,requested_games:ranked.length,credits_budget:MAX_DEEP_MARKET_CREDITS,credits_attempted:credits,markets:[...marketsUsed],quota_remaining:LAST_ODDS_META?.remaining??null,note:`Research Budget Engine spent up to ${credits}/${MAX_DEEP_MARKET_CREDITS} deep-market credits on ${ranked.length} evidence-priority MLB game(s).`};
  }
  const analyses=prelim.map(a=>({event:a.event,projection:a.projection,market:chooseMarket(a.event,a.projection),deep_market_error:a.deep_market_error||null}));
  const valid=analyses.map(a=>a.market.best).filter(Boolean),extreme=valid.filter(c=>(c.independent_disagreement||0)>=.10); const extremeRatio=extreme.length/Math.max(1,valid.length),isNcaaf=capped.some(e=>e.sport_key==='americanfootball_ncaaf'),isMlb=capped.some(e=>e.sport_key==='baseball_mlb'); const slateSanity={triggered:extreme.length>=3&&extremeRatio>=.30,severe:isNcaaf&&extreme.length>=4&&extremeRatio>=.40,extreme_count:extreme.length,candidate_count:valid.length,ratio:extremeRatio,message:''}; if(slateSanity.triggered){slateSanity.message=slateSanity.severe?`Market Sanity Firewall ESCALATED: ${extreme.length} of ${valid.length} top NCAAF candidates show ≥10-point independent/market disagreement. Extreme low-evidence candidates are CUT; other extreme candidates are capped at WATCH until stronger confirmation.`:`Market Sanity Firewall triggered: ${extreme.length} of ${valid.length} top candidates show ≥10-point independent/market disagreement. Extreme candidates are capped at WATCH until stronger confirmation.`; for(const a of analyses){const c=a.market.best;if(!c)continue; if(slateSanity.severe&&(c.independent_disagreement||0)>=.10&&((c.market_support_strength||0)<60||(c.market_coverage||0)<75||(c.market_edge_count||0)<2)){c.tier='PASS';c.sanity_flags=[...(c.sanity_flags||[]),slateSanity.message,'Slate-level evidence gate: extreme disagreement plus weak support/coverage/edge breadth is an automatic CUT.'];} else if((c.independent_disagreement||0)>=.08&&['CORE','SECONDARY'].includes(c.tier)){c.tier='WATCH';c.sanity_flags=[...(c.sanity_flags||[]),slateSanity.message];}}
    // MLB slate hygiene: when the sanity firewall is active, keep only the three
    // strongest WATCH candidates visible and CUT the rest. This prevents a long
    // watchlist from looking like hidden action when the market/model conflict is broad.
    if(isMlb){
      const watches=analyses.filter(a=>a.market.best&&a.market.best.tier==='WATCH').sort((a,b)=>candidateRank(b.market.best)-candidateRank(a.market.best));
      for(const a of watches.slice(3)){a.market.best.tier='PASS';a.market.best.sanity_flags=[...(a.market.best.sanity_flags||[]),'MLB watchlist-cap gate: Market Sanity Firewall is active, so only the top three WATCH candidates remain visible; this candidate is an automatic CUT for slate hygiene.'];}
      if(watches.length>3)slateSanity.message += ` MLB watchlist cap active: only the top 3 WATCH candidates remain visible; ${watches.length-3} additional HOLD candidates were CUT.`;
    }
  }
  const released=[]; const passes=[]; for(const a of analyses){ const c=a.market.best,p=a.projection; if(!c||c.tier==='PASS'){passes.push({event_id:a.event.id,matchup:`${a.event.away_team} @ ${a.event.home_team}`,reason:!c?'No verified market matched the independent projection.':((c.sanity_flags||[]).find(x=>/automatic CUT|no-support gate|comparable-data gate|Slate-level evidence gate|MLB support gate|MLB probable-starter gate|MLB watchlist-cap gate/i.test(x))||`Release gates failed: DQ ${p.data_quality.toFixed(0)}, market coverage ${(c.market_coverage??p.coverage_score??0).toFixed(0)}, market effective agreement ${(c.market_effective_agreement??p.effective_agreement??p.model_agreement).toFixed(0)}, support ${(c.market_support_strength??0).toFixed(0)}, market-specific edges ${c.market_edge_count??p.independent_edge_count}, adjusted edge ${fmtPct(c.adjusted_edge)} vs cushion ${fmtPct(c.cushion)}.`)});continue;} released.push({event_id:a.event.id,event:a.event,projection:p,...c,why:buildWhy(p,c),how_it_loses:p.risks.slice(0,4),timing:timing(a.event,c,p),final_verification:finalVerification(p,c),units:c.tier==='CORE'?1:c.tier==='SECONDARY'?.5:0}); }
  released.sort((x,y)=>candidateRank(y)-candidateRank(x)); let cores=0; for(const p of released){ if(p.tier==='CORE'){cores++;if(cores>2){p.tier='SECONDARY';p.units=.5;p.final_verification+=' Precision Mode Core cap downgraded this play.';}} }
  const eligible=released.filter(x=>['CORE','SECONDARY'].includes(x.tier)&&x.hard_rock&&x.fair_probability>=.56&&(x.independent_disagreement||0)<.08).slice(0,3); let parlay=null; if(eligible.length>=2){ const legs=eligible.slice(0,2); let dec=1; for(const l of legs)dec*=l.price>0?1+l.price/100:1+100/(-l.price); const american=dec>=2?Math.round((dec-1)*100):Math.round(-100/(dec-1)); parlay={units:.25,legs:legs.map(l=>({event_id:l.event_id,selection:l.selection,point:l.point,market:l.market,price:l.price,book:l.book})),approx_american:american,rationale:'Optional only: both legs independently cleared straight-bet release gates, use distinct games, have verified Hard Rock quotes, and do not carry extreme market-disagreement flags.'}; }
  const grade=released.filter(x=>x.tier==='CORE').length>=2?'A':released.some(x=>x.tier==='CORE')?'B+':released.some(x=>x.tier==='SECONDARY')?'B':'PASS-HEAVY';
  const slateCandidates=analyses.map(a=>a.market?.best).filter(Boolean),slateMetrics={
    games:analyses.length,
    avg_data_quality:mean(analyses.map(a=>a.projection?.data_quality))||0,
    avg_coverage:mean(slateCandidates.map(c=>c.market_coverage))||0,
    avg_support:mean(slateCandidates.map(c=>c.market_support_strength))||0,
    avg_decision_quality:mean(slateCandidates.map(c=>c.decision_quality))||0,
    hard_rock_coverage:safeDiv(slateCandidates.filter(c=>c.hard_rock).length,Math.max(1,slateCandidates.length),0),
    extreme_disagreements:slateCandidates.filter(c=>(c.independent_disagreement||0)>=.10).length
  };
  return {version:VERSION,generated_at:new Date().toISOString(),slate_grade:grade,slate_sanity:slateSanity,slate_metrics:slateMetrics,deep_market_scan:deepMeta,plays:released,passes,parlay,analyses}; }

